<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
final class SchoolExpenses {
 public function __construct(public FinanceAccess $fin){}
 public function setup(Request $r):array{[$sid,$scope]=$this->fin->context($r);return ['school'=>DB::table('schools')->where('id',$sid)->first(['name','code']),'today'=>$this->fin->today(),'campuses'=>DB::table('campuses')->where('school_id',$sid)->whereIn('id',$scope)->orderBy('name')->get(['id','name','status']),'categories'=>DB::table('expense_categories')->where('school_id',$sid)->orderBy('name')->get(),'banks'=>DB::table('bank_accounts')->where('school_id',$sid)->where(fn($q)=>$q->whereNull('campus_id')->orWhereIn('campus_id',$scope))->get(['id','name','campus_id','account_reference']),'can_manage'=>$this->fin->can($r,'finance.manage'),'can_approve'=>$this->fin->can($r,'finance.approve')];}
 public function category(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->fin->lock($r,'finance.manage');if(DB::table('expense_categories')->where('school_id',$sid)->where('code',$d['code'])->exists())$this->fin->fail('This category code already exists.');$id=DB::table('expense_categories')->insertGetId($d+['school_id'=>$sid,'created_at'=>now(),'updated_at'=>now()]);$this->fin->audit($r,'category_created','expense_categories',$id,$d);return ['message'=>'Expense category created.','id'=>$id];});}
 public function bank(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->fin->lock($r,'finance.approve');$this->fin->campus($r,$d['campus_id'],true);if(DB::table('bank_accounts')->where('school_id',$sid)->where('campus_id',$d['campus_id'])->where('name',$d['name'])->exists())$this->fin->fail('This campus account name already exists.');$id=DB::table('bank_accounts')->insertGetId($d+['school_id'=>$sid,'opening_balance'=>'0.00','created_at'=>now(),'updated_at'=>now()]);$this->fin->audit($r,'bank_created','bank_accounts',$id,$d);return ['message'=>'Paying account created.','id'=>$id];});}
 public function create(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->fin->lock($r,'finance.manage');$this->fin->campus($r,$d['campus_id'],true);$this->fin->row('expense_categories',$sid,$d['category_id']);$this->fin->bank($r,$d['campus_id'],$d['method'],$d['bank_account_id']??null,$d['reference']??null);if($d['incurred_on']>$this->fin->today())$this->fin->fail('Expense date cannot be in the future.');$d['amount']=$this->fin->money($this->fin->cents($d['amount']));$hash=hash('sha256',json_encode($d));$old=DB::table('expenses')->where('school_id',$sid)->where('entry_key',$d['entry_key'])->first();if($old){$this->fin->campus($r,$old->campus_id);if($old->request_hash!==$hash)$this->fin->fail('This expense key was already used for different details.');return ['id'=>$old->id,'message'=>'Expense request already saved.'];}$id=DB::table('expenses')->insertGetId($d+['school_id'=>$sid,'requested_by'=>$this->fin->access->membership($r)->id,'request_hash'=>$hash,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);$this->fin->audit($r,'expense_requested','expenses',$id,$d);return ['id'=>$id,'message'=>'Expense requested for approval.'];});}
 public function listing(Request $r,array $d){[$sid,$scope]=$this->fin->context($r);$this->fin->campus($r,$d['campus_id']);$q=DB::table('expenses as e')->join('expense_categories as c','c.id','=','e.category_id')->where('e.school_id',$sid)->where('e.campus_id',$d['campus_id']);if(!empty($d['status']))$q->where('e.status',$d['status']);if(!empty($d['search']))$q->where(fn($q)=>$q->where('e.description','like','%'.$d['search'].'%')->orWhere('e.payee','like','%'.$d['search'].'%'));return $q->orderByDesc('e.id')->paginate(20,['e.id','e.campus_id','e.amount','e.description','e.incurred_on','e.status','e.method','e.payee','e.paid_on','e.lock_version','c.name as category']);}
 public function detail(Request $r,int $id):array{[$sid]=$this->fin->context($r);$e=$this->fin->row('expenses',$sid,$id);$this->fin->campus($r,$e->campus_id);$e->snapshot=$e->snapshot?json_decode($e->snapshot,true):null;unset($e->entry_key,$e->payment_key,$e->request_hash);return ['expense'=>$e,'category'=>$this->fin->row('expense_categories',$sid,$e->category_id),'campus'=>$this->fin->row('campuses',$sid,$e->campus_id),'school'=>DB::table('schools')->where('id',$sid)->first(['name','code']),'reversals'=>DB::table('expense_reversals')->where('school_id',$sid)->where('expense_id',$id)->orderByDesc('id')->get(['id','kind','amount','method','effective_on','reason','status','reference','review_note','reviewed_at'])];}
 public function action(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->fin->lock($r,$d['action']==='pay'?'finance.manage':'finance.approve');$e=$this->fin->row('expenses',$sid,$id);$this->fin->campus($r,$e->campus_id);$mid=$this->fin->access->membership($r)->id;if($d['action']==='pay'&&$e->status==='paid'&&$e->payment_key===$d['payment_key']){if($e->paid_on!==$d['paid_on'])$this->fin->fail('Payment retry has different details.');return ['message'=>'Expense payment already recorded.'];}if($e->lock_version!=$d['lock_version'])$this->fin->fail('Expense changed. Reload before continuing.');$v=['lock_version'=>$e->lock_version+1,'updated_at'=>now()];if($d['action']==='pay'){if($e->status!=='approved'||!$e->approved_by)$this->fin->fail('Approve the expense before recording payment.');if(!$e->requested_by||!$e->payee)$this->fin->fail('Legacy expense request metadata needs review before payment.');if($d['paid_on']<$e->incurred_on||$d['paid_on']>$this->fin->today())$this->fin->fail('Choose a payment date between expense date and today.');if(DB::table('expenses')->where('school_id',$sid)->where('payment_key',$d['payment_key'])->exists())$this->fin->fail('Payment key already used.');$this->fin->bank($r,$e->campus_id,$e->method,$e->bank_account_id,$e->reference);$school=DB::table('schools')->where('id',$sid)->first();$snapshot=['school_name'=>$school->name,'school_code'=>$school->code,'campus_name'=>$this->fin->row('campuses',$sid,$e->campus_id)->name,'category_name'=>$this->fin->row('expense_categories',$sid,$e->category_id)->name,'payee'=>$e->payee,'description'=>$e->description,'amount'=>$e->amount,'method'=>$e->method,'reference'=>$e->reference,'paid_on'=>$d['paid_on'],'paid_by'=>$r->user()->name];$v+=['status'=>'paid','paid_on'=>$d['paid_on'],'paid_by'=>$mid,'payment_key'=>$d['payment_key'],'snapshot'=>json_encode($snapshot)];}elseif($d['action']==='void'){if($e->status!=='approved')$this->fin->fail('Only unpaid approved expenses can be voided.');$v+=['status'=>'rejected'];}else{if($e->status!=='pending')$this->fin->fail('Only pending expenses can be reviewed.');$v+=['status'=>$d['action']==='approve'?'approved':'rejected','approved_by'=>$mid,'approved_at'=>now()];}$this->fin->audit($r,'expense_'.$d['action'],'expenses',$id,['before'=>$e,'after'=>$v,'reason'=>$d['reason']??null]);DB::table('expenses')->where('school_id',$sid)->where('id',$id)->update($v);return ['message'=>$d['action']==='pay'?'Expense payment recorded.':'Expense review recorded.'];});}
 public function requestReversal(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->fin->lock($r,'finance.manage');$e=$this->fin->row('expenses',$sid,$id);$this->fin->campus($r,$e->campus_id);if($e->status!=='paid'||!$e->snapshot)$this->fin->fail('Reversals require a paid expense with a receipt.');if($d['effective_on']<$e->paid_on||$d['effective_on']>$this->fin->today())$this->fin->fail('Choose a correction/refund date between payment and today.');$amount=$this->fin->cents($d['amount']);if($d['kind']==='correction'&&($amount!==$this->fin->cents($e->amount)||$d['method']!==$e->method||($d['bank_account_id']??null)!=$e->bank_account_id))$this->fin->fail('A book correction must reverse the full original amount to its original account. Use refund for returned funds.');$this->fin->bank($r,$e->campus_id,$d['method'],$d['bank_account_id']??null,$d['reference']??null);$d['amount']=$this->fin->money($amount);$hash=hash('sha256',json_encode($d+['expense_id'=>$id]));$old=DB::table('expense_reversals')->where('school_id',$sid)->where('entry_key',$d['entry_key'])->first();if($old){if($old->request_hash!==$hash)$this->fin->fail('Reversal retry has different details.');return ['id'=>$old->id,'message'=>'Expense reversal already requested.'];}$reserved=(int)DB::table('expense_reversals')->where('school_id',$sid)->where('expense_id',$id)->whereIn('status',['pending','approved'])->selectRaw('COALESCE(SUM(amount)*100,0) as n')->value('n');if($amount<=0||$amount+$reserved>$this->fin->cents($e->amount))$this->fin->fail('Reversal exceeds the expense amount available.');$rid=DB::table('expense_reversals')->insertGetId($d+['school_id'=>$sid,'expense_id'=>$id,'request_hash'=>$hash,'status'=>'pending','requested_by'=>$this->fin->access->membership($r)->id,'created_at'=>now(),'updated_at'=>now()]);$this->fin->audit($r,'expense_reversal_requested','expense_reversals',$rid,$d);return ['id'=>$rid,'message'=>'Expense reversal requested.'];});}
 public function reviewReversal(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->fin->lock($r,'finance.approve');$v=$this->fin->row('expense_reversals',$sid,$id);$e=$this->fin->row('expenses',$sid,$v->expense_id);$this->fin->campus($r,$e->campus_id);if($v->status!=='pending')$this->fin->fail('This reversal was already reviewed.');if($d['action']==='approve'){$used=(int)DB::table('expense_reversals')->where('school_id',$sid)->where('expense_id',$e->id)->where('status','approved')->selectRaw('COALESCE(SUM(amount)*100,0) as n')->value('n');if($used+$this->fin->cents($v->amount)>$this->fin->cents($e->amount))$this->fin->fail('Reversal exceeds remaining payment.');}$values=['status'=>$d['action']==='approve'?'approved':'rejected','approved_by'=>$this->fin->access->membership($r)->id,'reviewed_at'=>now(),'review_note'=>$d['reason'],'updated_at'=>now()];DB::table('expense_reversals')->where('school_id',$sid)->where('id',$id)->update($values);$this->fin->audit($r,'expense_reversal_reviewed','expense_reversals',$id,$values);return ['message'=>'Expense reversal reviewed.'];});}
}
